"""Core rituals 2–5, transcribed from supplied PDF pages 277–284.

The five reviewed level 1 entries are retained. Wards and circles include their
complete shared rules rather than requiring a second search during play.
"""
import json,sys
from pathlib import Path
repo=Path(__file__).resolve().parent.parent
work=Path(sys.argv[1]);source=next(s for s in json.loads((work/'pages/manifest.json').read_text(encoding='utf-8')) if s['id']=='core-v5')
titles={'Descrição':'Description','Ingredientes':'Ingredients','Processo':'Process','Sistema':'System','Parada':'Dice Pool','Duração':'Duration','Exceções':'Exceptions'}
entries=[]
def ritual(slug,pt,en,level,pages,sections_pt,sections_en,*,cost=None,time=None,pool=None,aliases=None):
    id='core-v5-ritual-'+slug
    descriptions={}
    for locale,sections in [('pt-BR',sections_pt),('en',sections_en)]:
        eng=locale=='en'
        values=[{'title':titles.get(k,k) if eng else k,'text':v} for k,v in sections]
        values.insert(1,{'title':'Requirements' if eng else 'Requisitos','text':f'{"Blood Sorcery" if eng else "Feitiçaria de Sangue"} {level}.'})
        values.insert(2,{'title':'Cost' if eng else 'Custo','text':cost[1 if eng else 0] if cost else 'One Rouse Check.' if eng else 'Um Teste de Sangue.'})
        values.insert(3,{'title':'Casting time' if eng else 'Tempo de realização','text':time[1 if eng else 0] if time else f'{5*level} minutes unless the process specifies otherwise.' if eng else f'{5*level} minutos, salvo tempo específico no processo.'})
        if not any(s['title']==('Dice Pool' if eng else 'Parada') for s in values):values.append({'title':'Dice Pool' if eng else 'Parada','text':pool[1 if eng else 0] if pool else f'Intelligence + Blood Sorcery, Difficulty {level+1}.' if eng else f'Inteligência + Feitiçaria de Sangue, Dificuldade {level+1}.'})
        values.append({'title':'Learning and general limits' if eng else 'Aprendizado e limites gerais','text':f'Costs {level*3} XP and at least {level*level} weeks to learn, with Blood Sorcery at least equal to the Ritual level. Unlike Discipline powers, Rituals are learned separately. Beneficial Rituals normally affect only the caster unless explicitly stated otherwise. Requires the specified ingredients and uninterrupted concentration where applicable.' if eng else f'Custa {level*3} XP e no mínimo {level*level} semanas para aprender, com Feitiçaria de Sangue ao menos igual ao nível do Ritual. Rituais são aprendidos separadamente dos poderes. Rituais benéficos normalmente afetam apenas o conjurador, salvo exceção explícita. Exigem os ingredientes e a concentração ininterrupta especificados, quando aplicável.'})
        descriptions[locale]=values
    refs=sorted(set([274,276]+pages))
    entry={'id':id,'kind':'ritual','names':{'pt-BR':pt,'en':en},'aliases':list(dict.fromkeys([pt,en]+(aliases or []))),'discipline':'Feitiçaria de Sangue','level':level,'versions':[{'id':id+'-core','book':'core-v5','sourceTitle':'Livro Básico V5, pp. '+', '.join(str(p-2) for p in refs),'sourceLanguage':'pt-BR','pdfSha256':source['sha256'],'pages':[{'pdfPage':p,'printedPage':p-2} for p in refs],'requirements':{'disciplines':{'Feitiçaria de Sangue':level}},'descriptions':descriptions}]}
    (repo/'scripts/reviewed-content'/('core-ritual-'+slug+'.json')).write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8');entries.append(entry)

for slug,pt,en,level,page,ingredient_pt,ingredient_en,exception_pt,exception_en in [
('ward-against-spirits','Proteção contra Espíritos','Ward Against Spirits',2,279,'Um punhado de sal, ou pó de tijolo em algumas versões, misturado com Sangue.','A handful of salt, or brick dust in some versions, mixed with Blood.','Afeta aparições, fantasmas e espíritos elementais incorpóreos. Tentar manipular ou atravessar o objeto aciona a Proteção.','Affects incorporeal wraiths, ghosts and elemental spirits. Attempting to manipulate or pass through the object triggers the Ward.'),
('ward-against-lupines','Proteção contra Lupinos','Ward Against Lupines',3,281,'Um punhado de prata em pó misturado com Sangue.','A handful of silver dust mixed with Blood.','Afeta lobisomens em qualquer forma; tentar tocar o objeto aciona a Proteção.','Affects werewolves in any form; attempting to touch the object triggers the Ward.'),
('ward-against-cainites','Proteção contra Cainitas','Ward Against Cainites',4,282,'Cinzas quentes de um fogo ainda aceso.','Hot ashes from a fire still burning.','Afeta todos os vampiros exceto o conjurador. O uso das cinzas arrisca Frenesi de Terror; não pode inscrever esta Proteção na noite em que sucumbiu a esse Frenesi. Vampiro que examine com Auspícios pode ler o nome do conjurador vencendo Inteligência + Auspícios contra Inteligência + Feitiçaria de Sangue dele.','Affects all vampires except the caster. Handling the ashes risks terror frenzy; cannot inscribe this Ward on a night when the caster succumbed to that frenzy. A vampire examining it with Auspex can read the caster’s name by winning Intelligence + Auspex against their Intelligence + Blood Sorcery.')]:
    ritual(slug,pt,en,level,[277,page],[
    ('Descrição',exception_pt),('Ingredientes',ingredient_pt),('Processo','Derrame Sangue no objeto e desenhe o glifo com dedo nu. Limpar o Sangue torna a Proteção invisível. Cobre aproximadamente um metro: pode proteger um volante, mas não um carro inteiro.'),('Sistema','Não role até o primeiro intruso tocar a Proteção. Vitória causa 1 dano agravado à Vitalidade; crítico causa 3. A rolagem inicial vale para os demais intrusos. Quem já foi afetado precisa gastar 1 Vontade e vencer Vigor + Determinação, Dificuldade 4 (7 se a Proteção teve crítico), para tentar tocar de novo.'),('Exceções','Contato forçado não ativa: golpear com espada protegida não aciona, tentar pegá-la aciona. Roupa e luvas não protegem. Sentir o Invisível detecta com Inteligência + Auspícios contra Inteligência + Feitiçaria de Sangue do conjurador. Conhecer a Proteção não concede seu Círculo, nem o inverso.'),('Duração','Até o objeto ser destruído ou quebrado fisicamente; o intruso não pode fazer isso.')],[
    ('Descrição',exception_en),('Ingredientes',ingredient_en),('Processo','Pour Blood onto the object and draw the glyph with a bare finger. Wiping away the Blood makes the Ward invisible. Covers approximately one meter: it can protect a steering wheel but not a whole car.'),('Sistema','Do not roll until the first intruder touches the Ward. A win inflicts 1 Aggravated Health damage; a critical inflicts 3. The initial roll applies to later intruders. An already affected intruder must spend 1 Willpower and win Stamina + Resolve, Difficulty 4 (7 if the Ward achieved a critical), to try touching it again.'),('Exceções','Forced contact does not trigger it: striking with a warded sword does not, attempting to pick it up does. Clothes and gloves offer no protection. Sense the Unseen detects it with Intelligence + Auspex opposed by the caster’s Intelligence + Blood Sorcery. Knowing the Ward does not grant its Circle, or vice versa.'),('Duração','Until the object is physically destroyed or broken; the intruder cannot do this.')])

for slug,pt,en,level,page,ingredient_pt,ingredient_en,extra_pt,extra_en in [
('warding-circle-against-ghouls','Círculo de Proteção contra Carniçais','Warding Circle Against Ghouls',2,279,'Desenhe com um osso humano mergulhado em Sangue.','Draw with a human bone dipped in Blood.','',''),
('warding-circle-against-spirits','Círculo de Proteção contra Espíritos','Warding Circle Against Spirits',3,280,'Desenhe com faca de ferro mergulhada em sal e Sangue.','Draw with an iron knife dipped in salt and Blood.','Um ocultista humano pode reconstruir uma versão funcional com Inteligência + Ocultismo, Dificuldade 6, mas não conjurá-la sem Vitae ou outra ajuda sobrenatural.','A human occultist can reconstruct a working version with Intelligence + Occult, Difficulty 6, but cannot cast it without Vitae or other supernatural assistance.'),
('warding-circle-against-lupines','Círculo de Proteção contra Lupinos','Warding Circle Against Lupines',4,281,'Desenhe com faca de prata mergulhada em acônito e Sangue.','Draw with a silver knife dipped in wolfsbane and Blood.','',''),
('warding-circle-against-cainites','Círculo de Proteção contra Cainitas','Warding Circle Against Cainites',5,282,'Desenhe com varinha de sorveira mergulhada em Sangue e cinzas de fogueira ainda acesa.','Draw with a rowan wand dipped in Blood and ashes from a fire still burning.','','')]:
    ritual(slug,pt,en,level,[277,278,page],[
    ('Descrição','Impede que o tipo de intruso indicado no nome atravesse o círculo.'+(' '+extra_pt if extra_pt else '')),('Ingredientes',ingredient_pt+' Círculos exigem três vezes os ingredientes de uma Proteção comum do mesmo tipo.'),('Processo','Pinte no chão ou solo um círculo de até três metros de raio, com Sangue e pentáculos. Normalmente impede entrada, não saída; inscreva apontando para dentro para prender intruso já cercado.'),('Sistema','Quando o intruso cruza, confronte Inteligência + Feitiçaria de Sangue com a Vontade dele. Falha permite entrar. Vitória causa 3 danos superficiais à Vitalidade e impede a entrada; crítico causa 3 agravados. Intruso gasta 1 Vontade para tentar novamente. Se entrar e sair, repete sua metade do conflito para reentrar, mantendo o resultado inicial do conjurador. Pode usar o resultado anotado do Ritual original do círculo de longa duração.'),('Duração','Até o amanhecer; a versão de uma noite inteira de preparação e teste com Dificuldade +2 dura um ano e um dia.'),('Exceções','Conhecer o círculo não concede a Proteção comum, nem o inverso.')],[
    ('Descrição','Prevents the intruder type named in the Ritual from crossing the circle.'+(' '+extra_en if extra_en else '')),('Ingredientes',ingredient_en+' Circles require three times the ingredients of a regular Ward of that type.'),('Processo','Paint a circle up to three meters in radius on ground or floor using Blood and pentacles. Normally blocks entry, not exit; inscribe it inward-facing to trap an intruder already enclosed.'),('Sistema','When an intruder crosses, oppose Intelligence + Blood Sorcery with their Willpower. Failure allows entry. A win inflicts 3 Superficial Health damage and bars entry; a critical inflicts 3 Aggravated. The intruder spends 1 Willpower to try again. After entering and leaving, they repeat their half of the contest to reenter, retaining the caster’s original result. The recorded original Ritual result of a long-lasting circle may be used.'),('Duração','Until dawn; spending an entire night preparing and rolling at +2 Difficulty makes it last a year and a day.'),('Exceções','Knowing the circle does not grant the regular Ward, or vice versa.')],cost=('Três Testes de Sangue.','Three Rouse Checks.'),pool=(f'Inteligência + Feitiçaria de Sangue contra Vontade do intruso. Para a versão de um ano e um dia, teste inicial de Ritual com Dificuldade {level+3}.',f'Intelligence + Blood Sorcery opposed by the intruder’s Willpower. For the year-and-a-day version, initial Ritual roll at Difficulty {level+3}.'))

ritual('communicate-with-kindred-sire','Comunicação com o Senhor','Communicate with Kindred Sire',2,[279],[
('Descrição','Usa o vínculo entre Senhor e cria para comunicação telepática distante.'),('Ingredientes','Um objeto que pertenceu ao Senhor e tigela de prata com água limpa.'),('Processo','Submerja o objeto, pingue seu Sangue e concentre-se na última lembrança do Senhor por até 30 minutos.'),('Sistema','Role após 15 minutos. Vitória permite conversa silenciosa em mão dupla por dez minutos depois de mais 15 minutos; crítico inicia imediatamente. Perturbação importante em qualquer ponta rompe o vínculo.'),('Duração','Dez minutos de comunicação, salvo interrupção.')],[
('Descrição','Uses the sire–childe bond for distant telepathic communication.'),('Ingredientes','An object formerly owned by the sire and a silver bowl of clean water.'),('Processo','Submerge the object, drip your Blood and concentrate on the last memory of the sire for up to 30 minutes.'),('Sistema','Roll after 15 minutes. A win permits ten minutes of silent two-way conversation after another 15 minutes; a critical starts immediately. Major disturbance at either end breaks the connection.'),('Duração','Ten minutes of communication unless interrupted.')],time=('De 15 a 30 minutos conforme o resultado.','15 to 30 minutes depending on the result.'),aliases=['Comunicação com o Senhor do Membro'])
ritual('illuminate-trail-of-prey','Iluminar o Rastro da Presa','Illuminate the Trail of Prey',2,[279],[
('Descrição','Mostra uma trilha incandescente sutil, visível apenas ao conjurador, deixada por pessoa conhecida.'),('Ingredientes','Fita de cetim branca.'),('Processo','Embeba a fita no próprio Sangue e acenda-a. Vitória faz a fita molhada arder como rastilho; o efeito começa quando ela termina de queimar.'),('Sistema','Siga o trajeto das últimas 24 horas, mesmo sem marcas físicas ou em cidade cheia. Para seguir, teste Inteligência + Sobrevivência com Dificuldade 6 menos a margem do Ritual.'),('Duração','Uma noite; duas num crítico.')],[
('Descrição','Shows a subtle glowing trail visible only to the caster, left by a known person.'),('Ingredientes','A white satin ribbon.'),('Processo','Soak the ribbon in your Blood and ignite it. A win makes the wet ribbon burn like a fuse; the effect begins once consumed.'),('Sistema','Follow the target’s route over the last 24 hours, even without physical tracks or in crowded cities. Tracking uses Intelligence + Survival at Difficulty 6 minus the Ritual margin.'),('Duração','One night; two on a critical.')])
ritual('eyes-of-babel','Olhos de Babel','Eyes of Babel',2,[279],[
('Descrição','Ingerir um olho e a língua permite ler e falar os idiomas conhecidos pela vítima.'),('Ingredientes','Um olho e uma língua frescos de uma pessoa.'),('Processo','Arranque, mastigue e engula os ingredientes; provavelmente causa uma Mácula. O Teste de Sangue dissolve-os sobrenaturalmente; depois role o Ritual.'),('Sistema','Vitória concede todos os idiomas da vítima no mesmo grau de domínio.'),('Duração','Uma semana; um mês num crítico.')],[
('Descrição','Eating an eye and tongue grants reading and speech in the victim’s languages.'),('Ingredientes','One fresh human eye and tongue.'),('Processo','Remove, chew and swallow the ingredients, likely causing a Stain. The Rouse Check supernaturally dissolves them; then roll the Ritual.'),('Sistema','A win grants all the victim’s languages at the same proficiency.'),('Duração','One week; one month on a critical.')])
ritual('truth-of-blood','Verdade do Sangue','Truth of Blood',2,[279,280],[
('Descrição','Mistura de sangue distingue verdade e mentira, podendo revelar detalhes subconscientes.'),('Ingredientes','Uma pitada de sangue do alvo.'),('Processo','Misture seu Sangue ao do alvo num recipiente grande o suficiente para mergulhar um dedo.'),('Parada','No lugar do teste de Ritual padrão, Determinação + Feitiçaria de Sangue contra Autocontrole + Ocultismo para cada afirmação.'),('Sistema','Mergulhe o dedo e confronte cada afirmação. Vitória revela se é verdade até onde o alvo sabe. Crítico o faz ampliar involuntariamente a resposta com detalhes antes apenas entrevistos ou subconscientes; o Narrador avisa se não houver mais informação. A primeira falha termina o Ritual. Não atravessa Nublar Memória, Mente Esquecida ou outros apagamentos: pode inferir a causa da lacuna, não recuperar a lembrança.'),('Duração','Até a primeira falha ou fim da cena, quando a mistura que borbulha vira cinza.')],[
('Descrição','A blood mixture distinguishes truth from lies and may reveal subconscious details.'),('Ingredientes','A small amount of the target’s blood.'),('Processo','Mix your Blood with the target’s in a vessel large enough to dip a finger.'),('Parada','Instead of the standard Ritual roll, Resolve + Blood Sorcery opposed by Composure + Occult for each statement.'),('Sistema','Dip the finger and contest each statement. A win reveals truth as the target knows it. A critical makes them involuntarily expand the answer with half-glimpsed or subconscious details; the Storyteller says if none remain. The first failure ends the Ritual. It cannot penetrate Cloud Memory, The Forgetful Mind or other erasures: the cause of a gap may be inferred but the memory cannot be recovered.'),('Duração','Until the first failure or scene’s end, when the bubbling mixture becomes ash.')])
ritual('firewalker','Andarilho do Fogo','Firewalker',3,[280],[
('Descrição','Protege o conjurador ou companheiros de fogo.'),('Ingredientes','Ponta de um dedo da mão do próprio conjurador, tigela ou cálice dourado.'),('Processo','Arranque a ponta com Vigor + Determinação, Dificuldade 3, e queime-a com seu Sangue no recipiente. Chama azulada sinaliza o fim. A mutilação não causa dano suficiente para marcar a ficha, e regenera no sono diurno.'),('Sistema','O alvo sofre metade do dano de fogo pelo resto da noite. Pode beneficiar terceiros, mas cada ponta sacrificada deve ser do conjurador.'),('Duração','O restante da noite.')],[
('Descrição','Protects the caster or companions from fire.'),('Ingredientes','A fingertip from the caster’s own hand and a golden bowl or chalice.'),('Processo','Remove the fingertip with Stamina + Resolve, Difficulty 3, and burn it with your Blood in the vessel. A blue flame signals completion. The mutilation causes no track damage and regenerates during day sleep.'),('Sistema','The target takes half fire damage for the rest of the night. Can benefit others, but every sacrificed fingertip must belong to the caster.'),('Duração','The rest of the night.')])
ritual('dagons-call','O Chamado de Dagon','Dagon’s Call',3,[280],[
('Descrição','Rompe vasos sanguíneos à distância após expor a vítima ao Sangue do conjurador.'),('Ingredientes','Adaga cerimonial com incrustações de ouro.'),('Processo','A vítima precisa ter ingerido ou tocado seu Sangue, mesmo uma gota na pele. Espere ao menos uma hora e no máximo uma semana; perfure sua pele com a adaga e derrame Sangue no chão.'),('Parada','Determinação + Feitiçaria de Sangue contra Vigor + Determinação.'),('Sistema','Cada ponto de margem causa 1 dano agravado em mortal ou superficial em vampiro. Pode repetir o processo mais duas vezes, cada qual com Teste de Sangue adicional.'),('Duração','Até três aplicações; a exposição inicial é válida de uma hora a uma semana.')],[
('Descrição','Ruptures blood vessels at range after exposing the victim to the caster’s Blood.'),('Ingredientes','A gold-inlaid ceremonial dagger.'),('Processo','The victim must ingest or touch your Blood, even one drop on skin. Wait at least one hour but no more than one week; pierce your skin with the dagger and spill Blood on the ground.'),('Parada','Resolve + Blood Sorcery opposed by Stamina + Resolve.'),('Sistema','Each point of margin inflicts 1 Aggravated damage on a mortal or Superficial on a vampire. May repeat twice more, each requiring another Rouse Check.'),('Duração','Up to three applications; initial exposure remains valid from one hour to one week.')],aliases=["Dagon's Call"])
ritual('deflection-of-wooden-doom','Deflecção da Ruína de Madeira','Deflection of Wooden Doom',3,[280,281],[
('Descrição','A primeira estaca que realmente ameaçar o coração despedaça-se antes de penetrar.'),('Ingredientes','Lascas e rebarbas de madeira.'),('Processo','Misture madeira ao Sangue, desenhe um círculo e medite nele por uma hora; termine colocando uma lasca sob a língua.'),('Sistema','Só role o Ritual ao sofrer tentativa genuína de estacamento; apoiar uma estaca não ativa. Vitória despedaça a estaca ao tocar a pele. Crítico também cega o atacante por dois turnos com lascas.'),('Duração','Até o fim da noite ou remover a lasca da língua, o que ocorrer primeiro; protege a primeira tentativa.')],[
('Descrição','The first stake genuinely threatening the heart shatters before penetrating.'),('Ingredientes','Wood shavings and splinters.'),('Processo','Mix wood with Blood, draw a circle and meditate in it for one hour; finish by placing a splinter under the tongue.'),('Sistema','Roll only upon a genuine staking attempt; merely pressing a stake does not trigger it. A win shatters the stake on skin contact. A critical also blinds the attacker with splinters for two turns.'),('Duração','Until night’s end or removing the tongue splinter, whichever comes first; protects the first attempt.')],time=('Uma hora.','One hour.'))
ritual('essence-of-air','Essência do Ar','Essence of Air',3,[281],[
('Descrição','Poção concede voo limitado e ameaça a Máscara de modo evidente.'),('Ingredientes','Folhas e frutos de beladona.'),('Processo','Banha a beladona com Sangue e reduz a infusão entoando palavras de poder. Role ao reduzir: crítico produz duas doses. O conjurador sabe se deu certo.'),('Sistema','Só o conjurador pode usar a poção preta. Ao beber, voa ou flutua à velocidade de corrida. Pode carregar massa de um humano, reduzindo a velocidade para caminhada. Agarrar e voar com alguém involuntário, ou puxar o voador ao chão, usa conflito entre Força + Feitiçaria de Sangue e Força + Atletismo do oponente.'),('Duração','Poção conserva potência por uma noite; voo dura uma cena após ingerir.')],[
('Descrição','A potion grants limited flight and poses an obvious Masquerade risk.'),('Ingredientes','Belladonna leaves and berries.'),('Processo','Bathe belladonna in Blood and reduce the infusion while speaking words of power. Roll during reduction: a critical produces two doses. The caster knows whether it worked.'),('Sistema','Only the caster can use the black potion. Drinking allows flight or hovering at running speed. Carrying one human’s mass reduces speed to walking. Taking an unwilling passenger aloft or pulling the flyer down uses a contest between Strength + Blood Sorcery and the opponent’s Strength + Athletics.'),('Duração','Potion stays potent for one night; flight lasts one scene after drinking.')])
ritual('defense-of-sacred-haven','Defesa do Refúgio Sagrado','Defense of the Sacred Haven',4,[281],[
('Descrição','Escuridão mística protege o refúgio e seus ocupantes do sol.'),('Ingredientes','Apenas o Sangue do conjurador.'),('Processo','Inscreva sigilos ao redor e dentro da área, cuidando de portas, janelas e soleiras. Leva uma hora ou mais; raio máximo de seis metros. Ruínas ou áreas liminares dependem do Narrador.'),('Sistema','Role ao nascer do sol. Vitória impede visão para fora e todo dano solar a vampiros na área. Crítico permite enxergar vagamente o exterior. Sair da área a qualquer momento depois de completar a proteção faz o Ritual falhar ou terminar.'),('Duração','Um dia inteiro, salvo se o conjurador sair ou encerrar.')],[
('Descrição','Mystical darkness protects a haven and its occupants from the sun.'),('Ingredientes','Only the caster’s Blood.'),('Processo','Inscribe sigils around and within the area, attending to doors, windows and thresholds. Takes one hour or more; maximum radius six meters. Ruins or liminal areas depend on the Storyteller.'),('Sistema','Roll at sunrise. A win blocks outward sight and all sunlight damage to vampires within. A critical permits a dim view outside. Leaving at any time after completing the protection makes the Ritual fail or end.'),('Duração','One full day unless the caster leaves or ends it.')],time=('Uma hora ou mais, conforme a área.','One hour or more depending on the area.'))
ritual('eyes-of-nighthawk','Olhos do Falcão Noturno','Eyes of the Nighthawk',4,[281,282],[
('Descrição','Possui ave carnívora, como corvo ou ave de rapina, para guiá-la e ver por seus olhos. Papagaios e mainás não servem.'),('Ingredientes','Os olhos da ave, arrancados ao concluir o uso.'),('Processo','Alimente a ave com seu Sangue e entre em transe.'),('Sistema','Vitória controla voo e visão. Crítico permite ações simples como pegar objetos ou girar chaves e botões. Pode usar a maioria das Disciplinas não físicas pela ave; Dominação exige Telepatia ou outro meio de comunicação não verbal. Não há limite de distância. Se não arrancar os olhos da ave ao fim da noite, o próprio conjurador fica cego nas três noites seguintes.'),('Duração','Até o fim da noite; a omissão do sacrifício dos olhos causa a cegueira indicada.')],[
('Descrição','Possesses a carnivorous bird such as a raven or raptor to guide it and see through its eyes. Parrots and mynahs cannot be used.'),('Ingredientes','The bird’s eyes, removed at the end of use.'),('Processo','Feed the bird your Blood and enter a trance.'),('Sistema','A win controls flight and sight. A critical permits simple actions such as picking up objects or turning keys and dials. Most non-physical Disciplines can be used through the bird; Dominate requires Telepathy or another non-verbal communication method. No distance limit. Unless the bird’s eyes are removed at night’s end, the caster is blinded for the following three nights.'),('Duração','Until night’s end; omitting the eye sacrifice causes the stated blindness.')])
ritual('incorporeal-passage','Passagem Incorpórea','Incorporeal Passage',4,[282],[
('Descrição','Torna-se incorpóreo e atravessa objetos, permanecendo visível e audível.'),('Ingredientes','Um espelho.'),('Processo','Salpique Sangue no espelho, entoe o cântico e quebre-o.'),('Sistema','Vitória mantém a forma enquanto segurar um caco. Imune a dano físico, exceto fogo, sol e armas arcanas ou Rituais que firam espíritos. Não interage fisicamente, não faz Impulso de Sangue e não entra em reinos espirituais. Atravessa matéria em linha reta, sem mudar direção dentro dela. Se voltar ao material dentro de sólido, o Narrador decide consequências, de inconveniência a destruição ou emparedamento.'),('Duração','Uma cena ou até soltar o caco.')],[
('Descrição','Becomes incorporeal and passes through objects while remaining visible and audible.'),('Ingredientes','A mirror.'),('Processo','Splash Blood onto the mirror, chant and break it.'),('Sistema','A win maintains the form while holding a shard. Immune to physical damage except fire, sunlight, arcane weapons or Rituals harming spirits. Cannot interact physically, Blood Surge or enter spirit realms. Passes through matter in a straight line without turning inside it. Returning to material form within solid matter has consequences decided by the Storyteller, from inconvenience to destruction or entombment.'),('Duração','One scene or until dropping the shard.')])
ritual('heart-of-stone','Coração de Pedra','Heart of Stone',5,[282,283],[
('Descrição','Transforma o coração em pedra, impedindo estacamento e tornando o conjurador emocionalmente distante.'),('Ingredientes','Laje de pedra e vela de cera encharcadas com seu Sangue.'),('Processo','Deite-se na laje com a vela no peito e deixe-a queimar pela noite. Ao alcançar o peito, causa 1 dano agravado e exige resistir a Frenesi de Terror, Dificuldade 3. Falha encerra o Ritual. Se resistir, role o Ritual; crítico cura o dano da vela.'),('Sistema','Estacas não penetram o coração e quebram quando forçadas. Subtraia 3 dados de Remorso e rolagens Sociais ativas (não de resistência), exceto Intimidação e Dominação. Não pode usar Presença; recebe +3 dados para resistir a ela.'),('Duração','Indefinida; para reverter, repita o Ritual.')],[
('Descrição','Turns the heart to stone, preventing staking and making the caster emotionally detached.'),('Ingredientes','A stone slab and wax candle soaked with the caster’s Blood.'),('Processo','Lie on the slab with the candle on the chest and let it burn through the night. Reaching the chest inflicts 1 Aggravated damage and requires resisting terror frenzy at Difficulty 3. Failure ends the Ritual. If resisted, roll the Ritual; a critical heals the candle damage.'),('Sistema','Stakes cannot penetrate the heart and break when forced. Subtract 3 dice from Remorse and active Social rolls (not resistance), except Intimidation and Dominate. Cannot use Presence; gains +3 dice to resist it.'),('Duração','Indefinite; repeat the Ritual to reverse it.')],time=('Uma noite.','One night.'))
ritual('escape-to-true-sanctuary','Fuga para o Verdadeiro Santuário','Escape to True Sanctuary',5,[283],[
('Descrição','Liga dois círculos para viagem instantânea de mão única, com partida e chegada definidas.'),('Ingredientes','Dois círculos carbonizados de aproximadamente um metro de diâmetro.'),('Processo','Queime cada círculo no chão ou solo e consagre-o com duas horas de cânticos e dois Testes de Sangue por noite por três noites. O total é doze Testes de Sangue para o par.'),('Sistema','Entre no círculo de partida, concentre-se por um turno e role o Ritual, no máximo uma tentativa por cena. Vitória teleporta ao círculo de chegada sem limite de distância. Círculos devem estar no solo ou piso de construção, nunca veículo. Pode levar uma pessoa ou objetos de massa humana equivalente. Dano a qualquer círculo inutiliza ambos. Só pode manter um par ativo.'),('Duração','Os círculos permanecem até danificados; cada viagem exige teste e segue apenas a direção designada.')],[
('Descrição','Links two circles for instant one-way travel, with designated departure and arrival.'),('Ingredientes','Two charred circles approximately one meter in diameter.'),('Processo','Burn each circle into ground or floor and consecrate it with two hours of chanting and two Rouse Checks per night for three nights. Total cost is twelve Rouse Checks for the pair.'),('Sistema','Enter the departure circle, concentrate for one turn and roll the Ritual, at most once per scene. A win teleports to the arrival circle with no distance limit. Circles must be on ground or a building floor, never a vehicle. May bring one person or objects totaling a human’s mass. Damage to either circle disables both. Only one pair may be active.'),('Duração','Circles remain until damaged; each journey requires a roll and follows the designated direction only.')],cost=('Doze Testes de Sangue para preparar o par; a ativação usa o teste do Ritual descrito.','Twelve Rouse Checks to prepare the pair; activation uses the stated Ritual roll.'),time=('Três noites; duas horas por círculo em cada noite.','Three nights; two hours per circle each night.'))
ritual('shaft-of-belated-dissolution','Fuste de Extinção Tardia','Shaft of Belated Dissolution',5,[283,284],[
('Descrição','Cria estaca que busca o coração e causa Morte Final, podendo avançar como lasca dentro do corpo.'),('Ingredientes','Estaca de sorveira inscrita com runas perniciosas e fogo de carvalho.'),('Processo','Encharque a estaca com Sangue equivalente a dois Testes de Sangue, escurecendo-a no fogo e lendo encantos por cinco horas.'),('Sistema','Concede +3 dados a qualquer tentativa de estacar, corpo a corpo, besta ou martelo em vítima adormecida; qualquer pessoa pode manejá-la. Acerto com margem 5 ou mais reduz o vampiro a pó num turno. Se acertar com margem menor, a estaca quebra na ferida e sua ponta avança ao coração ao longo de horas ou noites. Sem extração médica ou mística, a Morte Final é certa. Outra pessoa pode extraí-la com Destreza + Medicina, Dificuldade 6, em até quatro horas; amputar o membro afetado também a remove, desde que ainda não tenha alcançado o tronco.'),('Duração','A fonte não define prazo de validade da estaca; a lasca permanece letal até extraída ou alcançar o coração.')],[
('Descrição','Creates a stake that seeks the heart and causes Final Death, potentially moving as a splinter inside the body.'),('Ingredientes','A rowan stake inscribed with baleful runes and an oak fire.'),('Processo','Soak the stake in Blood equivalent to two Rouse Checks while blackening it in the fire and reading incantations for five hours.'),('Sistema','Grants +3 dice to any staking attempt, by melee, crossbow or hammer against a sleeping victim; anyone can wield it. A hit with margin 5 or more turns the vampire to dust in one turn. A hit with lesser margin breaks the stake into the wound, its tip advancing toward the heart over hours or nights. Without medical or mystical removal, Final Death is certain. Another person can remove it with Dexterity + Medicine, Difficulty 6, taking up to four hours; amputating the affected limb also removes it unless it has reached the torso.'),('Duração','The source gives no expiry for the stake; the splinter remains lethal until removed or reaching the heart.')],cost=('Dois Testes de Sangue.','Two Rouse Checks.'),time=('Cinco horas.','Five hours.'))
for entry in entries:
    if 'warding-circle' not in entry['id']:continue
    for locale,description in entry['versions'][0]['descriptions'].items():
        section=next(s for s in description if s['title']==('Exceptions' if locale=='en' else 'Exceções'))
        section['text']+=' Sense the Unseen detects the Ward with Intelligence + Auspex opposed by the caster’s Intelligence + Blood Sorcery.' if locale=='en' else ' Sentir o Invisível detecta a Proteção com Inteligência + Auspícios contra Inteligência + Feitiçaria de Sangue do conjurador.'
        if 'cainites' in entry['id']:section['text']+=' Affects all vampires except the caster.' if locale=='en' else ' Afeta todos os vampiros exceto o conjurador.'
        if 'spirits' in entry['id']:section['text']+=' Affects incorporeal wraiths, ghosts and elemental spirits.' if locale=='en' else ' Afeta aparições, fantasmas e espíritos elementais incorpóreos.'
        if 'lupines' in entry['id']:section['text']+=' Affects werewolves in any form.' if locale=='en' else ' Afeta lobisomens em qualquer forma.'
    (repo/'scripts/reviewed-content'/('core-ritual-'+entry['id'].removeprefix('core-v5-ritual-')+'.json')).write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'{len(entries)} Core rituals 2–5 reviewed; level 1 entries preserved')
